corrected_sequence = ''
# empty string 

for letter in sequence: 
    if letter == 'A':
        corrected_sequence += 'T'
    
    if letter == 'C':
        corrected_sequence += 'G'

    if letter == 'T':
        corrected_sequence += 'A'

    if letter == 'G':
        corrected_sequence += 'C'
# to get the reverse, for the complement
complement_Sequence = corrected_sequence[::-1]

print(complement_Sequence)
